#!/usr/bin/env node
import {
  findProjectRoot
} from "./chunk-IWNALT6P.js";
import {
  ExitCode,
  GramCLIError
} from "./chunk-IXNX2GX7.js";

// src/core/glob.ts
import { globSync } from "tinyglobby";
import { resolve, extname } from "path";
async function resolveGlob(patterns) {
  const root = await findProjectRoot();
  const files = [];
  for (const pattern of patterns) {
    if (pattern.includes("*")) {
      let matches = [];
      try {
        matches = globSync(pattern, { cwd: root, absolute: true }).filter(
          (f) => extname(f) === ".gram"
        );
      } catch (err) {
        const code = err.code;
        if (code !== "ENOENT" && code !== "EACCES" && code !== "ENOTDIR")
          throw err;
      }
      files.push(...matches);
    } else {
      files.push(resolve(pattern));
    }
  }
  if (files.length === 0) {
    throw new GramCLIError(
      `No .gram files found for: ${patterns.join(", ")}`,
      ExitCode.Error
    );
  }
  return [...new Set(files)];
}

export {
  resolveGlob
};
